import{z as s,x as o,o as B,c as p,q as l,j as r,D as A,d as e,s as n,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"可转债打新与赎回","description":"","frontmatter":{"title":"可转债打新与赎回","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cb-call-put.md","filePath":"quant/cb-call-put.md","lastUpdated":1791413859000}'),d={name:"quant/cb-call-put.md"};function C(D,E,h,m,c,u){const t=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=l('<h1 id="可转债打新与赎回" tabindex="-1">可转债打新与赎回 <a class="header-anchor" href="#可转债打新与赎回" aria-label="Permalink to &quot;可转债打新与赎回&quot;">​</a></h1><div class="epigraph"><p>向不特定对象发行的可转债上市首日涨幅比例为百分之五十七点三、跌幅比例为百分之四十三点三，并实施百分之二十、百分之三十两档盘中临时停牌；次日起涨跌幅比例为百分之二十。有条件赎回与回售以募集说明书约定的计次窗口为准。</p><footer>—— 《上海证券交易所可转换公司债券交易实施细则》；上市公司可转债募集说明书中的赎回与回售条款</footer></div><p><a href="/quant/cn-block-trade">上一课</a>把大宗折价写成锁定与信息的覆盖：预披露、2% 上限与六个月锁定下，折价不保证次日向收盘回归。缺口是转债条款上的两场拍卖：信用申购加中签缴款不是无风险配售；有条件赎回通过 130% 与 15/30 计次把有效到期压缩到通知期。本课写打新、首日价格带与赎回/回售/下修，不重写停复牌指引。日常联立见 <a href="/quant/cb-equity-link">转债与正股联立</a>，定价核见 <a href="/quant/convertible-credit">可转债与信用混合</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开发行可转债实行信用申购：投资者在申购日按规则顶格或按额度申报，无需预缴全额保证金，中签后再缴款。中签率由网上发行规模与有效申购量决定，并受投资者适当性约束——开通转债交易权限通常要求申请前二十个交易日日均资产不低于十万元且具备二十四个月交易经验（以当时适当性细则为准）。中签却缴款失败会进入监管与券商的失信处理，下一次申购资格受损。因此「打新」的期望收益是</p> \\[\\mathbb{E}[\\text{中签份额}\\times (C_{\\mathrm{list}}-100)_+] - \\text{缴款占用与失败成本}, \\]<p>其中 \\(C_{\\mathrm{list}}\\) 受上市首日 57.3% / −43.3% 的硬顶，不是无限上涨的彩票。把历史首日涨幅的无条件均值当成未来期望，忽略了正股质地、条款（下修空间、评级）、发行规模与适当性实施后的中签率变化。</p><p>赎回是发行人的美式权利，不是到期兑付。典型有条件赎回：转股期内，正股在任意连续三十个交易日中至少十五个交易日的收盘价不低于当期转股价的 130%，发行人有权按面值加当期应计利息赎回未转股余额。触发后须公告是否行使；一旦行使，赎回条件触发日与赎回日的间隔不少于十五个交易日且不超过三十个交易日（以交易所与募集说明书为准）。通知期内持有人仍可转股或卖出。赎回价远低于此时的平价，理性持有人转股或卖出，剩余规模在赎回登记日附近收敛到零。把「强赎」理解成发行人按 100 元买回高价券，是把强制转股写成了现金收购。</p><p><span class="marginnote">术语翻译：「强赎」不是发行人拿现金把你的转债买回去，它更像逼你转股。触发条件本身就说明正股已远高于转股价，转股立刻比拿约 100 元的赎回价划算，理性持有人都会在通知期内转股或卖出——发行人由此把债变成股、免掉还款。</span></p><h3 id="上市首日价格带与临停" tabindex="-1">上市首日价格带与临停 <a class="header-anchor" href="#上市首日价格带与临停" aria-label="Permalink to &quot;上市首日价格带与临停&quot;">​</a></h3><p>首日以前一日（发行价）为前收盘，涨跌幅 57.3% 与 43.3%，盘中成交价相对发行价首次涨跌达 20% 停牌 30 分钟，达 30% 停牌至 14:57，跨越 14:57 则于 14:57 复牌再走收盘集合。次日起 20% 日限，不再走首日临停。首日定价因此是带两道冷却的受限拍卖，而不是连续的期权结算。中签持有人若把期望建立在「开盘直接封 57.3%」，会在 20% 临停复牌后的回撤上把纸面利润还回去。最后交易日证券简称加「Z」，提示到期或赎回前的最后撮合，流动性与溢价行为与存续期中段不同。</p><p><span class="marginnote">信用申购取消预缴，降低了资金门槛，也提高了无效申购与缴款违约的可能。期望收益必须扣掉中签后的缴款失败惩罚与资金在缴款到上市之间的占用，不能只用「中签率 × 平均首日涨幅」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>申购估值应分三步。第一，用正股价格、转股价、评级与下修条款估计上市后的合理全价区间，而不是用历史打新均值。第二，把首日合法价格带与临停当成执行约束，模拟开盘集合与 20%/30% 冷却后的可成交路径。第三，乘以中签率及缴款成功率，得到每股（每张）期望，再与资金占用天数比较。适当性实施后个人投资者数量变化会改变中签率，样本须从规则生效日切开。</p><p><span class="marginnote">数字实例：顶格申购 100 万元面值、中签率 0.003%，期望中签只有 30 元面值（0.3 张）。即使首日平均涨 25%，单次期望利润不足 10 元，还要扣掉缴款占用与失败惩罚——信用申购扩容后，「打新躺赚」已是薄利游戏，算期望必须乘中签率。</span></p><p>赎回估值把通知期写成强制转股期权。一旦发行人公告行使，转债的有效到期变为赎回日，\\(C\\) 应向 \\(\\max(P^{\\mathrm{parity}},C_{\\mathrm{call}})\\) 收敛，且 \\(C_{\\mathrm{call}}\\approx 100\\)。对冲上，delta 升向转股比例，正股供给在转股登记后增加，稀释落在公告后的正股路径里。未公告但已进入 15/30 计数的阶段，市场会给一个「发行人是否行使」的二元树：同一发行人可能为了保债或等待更高转股比例而暂不赎回，历史行使频率不能当成法定义务。</p><h3 id="回售、下修与到期兑付" tabindex="-1">回售、下修与到期兑付 <a class="header-anchor" href="#回售、下修与到期兑付" aria-label="Permalink to &quot;回售、下修与到期兑付&quot;">​</a></h3><p>有条件回售通常在最后两个计息年度：正股连续三十个交易日收盘价低于转股价的 70%，持有人有权按面值加应计利息回售。下修正是发行人用来打断这条计数的工具：下调转股价后，回售窗口重新起算，平价被抬高，回售被推远。下修须经股东大会等程序，持有人回避规则以募集说明书为准。到期未转股则按面值加最后一期利息兑付（或条款约定的到期赎回价）。三条退出——强赎转股、回售兑现、到期兑付——对应正股高、正股低且发行人未下修、以及时间耗尽。定价必须同时打开三条边界，不能只校准首日涨幅。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>打新的供给是发行规模，需求是适当性过滤后的有效申购。中签率低时，单户期望张数可以小于 1，方差来自中签伯努利而不是转债波动。上市后首日的买家包含未中签却看好条款的资金，价格发现在临停里分段完成。此后转债进入与正股联立的日常交易，打新的增量信息消失。</p><p>强赎公告把博弈从「会不会赎回」切换到「通知期内正股是否掉回转股价附近」。若正股大跌，持有人可能宁愿被赎回也不转股，发行人得到的转股稀释小于预期，转债价格会向赎回价而不是平价收敛。这是公告后常见的波动来源，不是「条款被破坏」。下修公告则使 \\(K\\) 下降、平价上升，转债相对旧平价的溢价跳降，相对新平价重新定价。用旧 \\(K\\) 去算公告日溢价变化，会把一次条款重估写成崩盘。</p>',21)),(B(),r(i,null,{default:A(()=>[n(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRIG%5B%2215%2F30%20%E8%AE%A1%E6%AC%A1%E6%BB%A1%E8%B6%B3%20130%25%22%5D%20--%3E%20ANN%5B%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E5%85%AC%E5%91%8A%E8%A1%8C%E4%BD%BF%E8%B5%8E%E5%9B%9E%22%5D%0A%20%20ANN%20--%3E%20WIN%5B%22%E9%80%9A%E7%9F%A5%E6%9C%9F%2015%E2%80%9330%20%E4%B8%AA%E4%BA%A4%E6%98%93%E6%97%A5%22%5D%0A%20%20WIN%20--%3E%20OK%5B%22%E6%AD%A3%E8%82%A1%E7%BB%B4%E6%8C%81%E9%AB%98%E4%BD%8D%22%5D%0A%20%20OK%20--%3E%20CONV%5B%22%E6%8C%81%E6%9C%89%E4%BA%BA%E8%BD%AC%E8%82%A1%E6%88%96%E5%8D%96%E5%87%BA%EF%BC%8C%E5%89%A9%E4%BD%99%E8%A7%84%E6%A8%A1%E5%BD%92%E9%9B%B6%22%5D%0A%20%20WIN%20--%3E%20CRASH%5B%22%E6%AD%A3%E8%82%A1%E6%8E%89%E5%9B%9E%E8%BD%AC%E8%82%A1%E4%BB%B7%E9%99%84%E8%BF%91%22%5D%0A%20%20CRASH%20--%3E%20ACC%5B%22%E8%BD%AC%E8%82%A1%E4%B8%8D%E5%A6%82%E8%B5%8E%E5%9B%9E%E4%BB%B7%EF%BC%8C%E5%AE%81%E6%84%BF%E8%A2%AB%E8%B5%8E%22%5D%0A%20%20ACC%20--%3E%20CAP%5B%22%E8%BD%AC%E5%80%BA%E5%90%91%E7%BA%A6%20100%20%E5%85%83%E8%B5%8E%E5%9B%9E%E4%BB%B7%E6%94%B6%E6%95%9B%EF%BC%8C%E7%A8%80%E9%87%8A%E5%B0%8F%E4%BA%8E%E9%A2%84%E6%9C%9F%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<p><span class="marginnote">赎回通知期不少于十五个交易日，是持有人转股的操作窗口，也是正股与转债的事件窗口。窗口内两边往往放量。把公告日单日收益当成全部事件收益，会漏掉通知期内向平价收敛的剩余路径。</span></p><h3 id="与美式赎回权模型的接口" tabindex="-1">与美式赎回权模型的接口 <a class="header-anchor" href="#与美式赎回权模型的接口" aria-label="Permalink to &quot;与美式赎回权模型的接口&quot;">​</a></h3><p>理论模型里的最优赎回发生在转股价值足够高于赎回价、且发行人仍能承受转股稀释的区域。监管与募集说明书把「足够高」写成 130% 与 15/30 计次，把通知期写成 15–30 个交易日，使连续时间的最优停时变成离散计次加强制窗口。校准 A 股转债赎回，应把这套管制定成障碍条件，而不是用无约束的美式赎回去拟合。信用差的发行人可能满足计次却选择不赎回，模型需要「行使强度」而不是 100% 行使假设。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把可转债打新写成无风险收益或发行套利教程。不要忽略首日涨跌幅与临停对上限的截断。不要在赎回公告后仍用原剩余年限做债底久期。不要把下修当成确定性的持有人福利——下修须表决，失败则回售风险上升。定向可转债、可交换债的申购与赎回不适用同一套公开发行细则。</p><p><span class="marginnote">常见误区：强赎公告后仍按原剩余年限算债底久期。公告一旦行使，转债的有效到期就从几年后变成两周后的赎回日；还用旧久期去对冲利率或信用风险，头寸会错得离谱。</span></p><p>容量上，网上打新的期望张数随发行规模与账户数变化，不能线性外推。强赎窗口的对冲容量受正股涨跌停与转债 20% 日限约束，事件日两边可能同时封板。报告应分开：申购期望（含中签与首日带）、存续期赎回/回售/下修事件收益、以及最后交易日「Z」标识后的收敛误差。</p><p><span class="marginnote">到期赎回与有条件赎回不是同一现金流。前者是债券到期兑付，后者是发行人在 130% 计次满足后的选择权。用「赎回」一个词覆盖两者，会把到期债底写成强赎冲击。</span></p>',8)),(B(),r(i,null,{default:A(()=>[n(t,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E4%BF%A1%E7%94%A8%E7%94%B3%E8%B4%AD%20%2F%20%E4%B8%AD%E7%AD%BE%E7%BC%B4%E6%AC%BE%22%5D%20--%3E%20LIST%5B%22%E4%B8%8A%E5%B8%82%E9%A6%96%E6%97%A5%EF%BC%9A57.3%25%2F-43.3%25%20%2B%2020%25%2F30%25%20%E4%B8%B4%E5%81%9C%22%5D%0A%20%20LIST%20--%3E%20TRADE%5B%22%E6%AC%A1%E6%97%A5%E8%B5%B7%2020%25%20%E4%B8%8E%E6%AD%A3%E8%82%A1%E8%81%94%E7%AB%8B%22%5D%0A%20%20TRADE%20--%3E%20CNT%5B%2215%2F30%20%E6%97%A5%E6%94%B6%E7%9B%98%E4%BB%B7%E7%9B%B8%E5%AF%B9%20K%20%E7%9A%84%20130%25%22%5D%0A%20%20CNT%20--%3E%7C%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E8%A1%8C%E4%BD%BF%22%7C%20CALL%5B%22%E9%80%9A%E7%9F%A5%E6%9C%9F%2015%E2%80%9330%20%E6%97%A5%EF%BC%9A%E8%BD%AC%E8%82%A1%E6%88%96%E5%8D%96%E5%87%BA%22%5D%0A%20%20TRADE%20--%3E%20PUT%5B%22%E6%9C%80%E5%90%8E%E4%B8%A4%E5%B9%B4%2070%25%20%E5%9B%9E%E5%94%AE%E7%AA%97%E5%8F%A3%22%5D%0A%20%20PUT%20--%3E%7C%22%E4%B8%8B%E4%BF%AE%E6%89%93%E6%96%AD%E8%AE%A1%E6%95%B0%22%7C%20KADJ%5B%22%E4%B8%8B%E8%B0%83%20K%EF%BC%8C%E9%87%8D%E8%AE%A1%E4%BB%B7%22%5D%0A%20%20TRADE%20--%3E%20MAT%5B%22%E5%88%B0%E6%9C%9F%E5%85%91%E4%BB%98%E6%9C%AA%E8%BD%AC%E8%82%A1%E4%BD%99%E9%A2%9D%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("h2",{id:"小结",tabindex:"-1"},[e("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[5]||(E[5]=a("ul",null,[a("li",null,"打新是信用申购加中签缴款，期望收益须扣中签率、缴款失败与首日价格带，不是无风险配售。"),a("li",null,"上市首日 57.3% / −43.3% 与 20%、30% 临停限制了价格发现路径。"),a("li",null,"有条件赎回通过 130% 与 15/30 计次触发，通知期内以强制转股为主，赎回价不是持有人的最优现金流。"),a("li",null,"回售与下修互为对手：下修打断 70% 计数并改写平价。"),a("li",null,"到期兑付、强赎转股、回售是三条不同边界，须同时进入条款日历。"),a("li",null,"出处：沪深交易所可转债交易实施细则（含 2022 年 8 月施行及后续修订）；《上市公司证券发行注册管理办法》关于转股价格修正与赎回的规定；具体计次与通知期以各券募集说明书为准。")],-1))])}const f=s(d,[["render",C]]);export{b as __pageData,f as default};
